"use client";

import { useRef, useState,useEffect } from "react";
import TopBar from "../TopBar";
import Sidebar from "./../Sidebar";
import "./profile.css";
import { Certificate } from "crypto";

export default function ProfilePage() {
  
  const [photoUrl, setPhotoUrl] = useState(null);
  const fileInputRef = useRef(null);
  
  const [user,setUser]=useState(null);

  const [name,setName]=useState('');
  const [familyName,setFamilyName]=useState('');
  const [dateNaissane,setDateNaissance]=useState('');
  const [ville,setVille]=useState('');
  const [num,setNum]=useState('');
  const [email,setEmail]=useState('');
  const [password,setPassword]=useState('');
  const [functionPoste,setFunctionPoste]=useState('');//defaultValue="Chefdepartement d'informatique
  const [lieuTravail,setlieuTravail]=useState('');
  const [certificate,setCertificate]=useState('');//defaultValue="doctorant ......."
  const [expirience,setExpirience]=useState(''); //defaultValue="Formation sur ......"

 
  useEffect(()=>{

       const token=localStorage.getItem("token");

       fetch('http://localhost:8000/api/profile',{
       
        headers:{
           "Accept" : "application/json",
            "Content-Type":"application/json",
             Authorization: `Bearer ${token}`,

        },
         credentials: "same-origin"
        //  credentials: "include",
  })
  .then(res=>{
    if(!res.ok)throw new Error('network response was not ok');
    return res.json();
  })
  .then(data=>{
    console.log(data);
    setUser(data);
  })
  .catch(err => console.error(err));

  },[]);
  
  //if(!user)return<div>Loading</div>;

  const handleChoosePhoto = () => {
    if (fileInputRef.current) fileInputRef.current.click();
  };

  const handlePhotoChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const url = URL.createObjectURL(file);
    setPhotoUrl(url);
  };

  return (
    <div className="page">
      <TopBar />
      <Sidebar />

      <div className="content">
        <div className="profile-wrapper">

          
          <section className="profile-card">
            <h2 className="card-title">Informations personal:</h2>

            <div className="personal-grid">

           
              <div className="photo-col">
                <div
                  className="photo-circle"
                  style={
                    photoUrl
                      ? {
                          backgroundImage: `url(${photoUrl})`,
                          backgroundSize: "cover",
                          backgroundPosition: "center",
                        }
                      : {}
                  }
                />
                <button className="photo-btn" type="button" onClick={handleChoosePhoto}>
                  Modifier la photo
                </button>

                <input
                  type="file"
                  accept="image/*"
                  ref={fileInputRef}
                  style={{ display: "none" }}
                  onChange={handlePhotoChange}
                />
              </div>

              
              <div className="personal-fields">
                <div className="field-row">
                  <div className="field">
                    <label>Nom :</label>
                    <input type="text" value={name} onChange={e => setName(e.target.value)}/>
                  </div>
                  <div className="field">
                    <label>Date de naissance</label>
                    <input type="date"  value={dateNaissane} onChange={e => setDateNaissance(e.target.value)}/>
                  </div>
                </div>

                <div className="field-row">
                  <div className="field">
                    <label>Prénom :</label>
                    <input type="text"  value={familyName} onChange={e => setFamilyName(e.target.value)}/>
                  </div>
                  <div className="field">
                    <label>Ville :</label>
                    <input type="text"  value={ville} onChange={e => setVille(e.target.value)}/>
                  </div>
                </div>

                <div className="field-row">
                  <div className="field full">
                    <label>Numéro de téléphone :</label>
                    <input type="text"  value={num} onChange={e => setNum(e.target.value)} />
                  </div>
                </div>
              </div>
            </div>
          </section>

         
          <section className="profile-card">
            <h2 className="card-title">Informations sur l’emploi :</h2>

            <div className="job-grid">
              <div className="field-row">
                <div className="field">
                  <label>Email :</label>
                  <input type="email"  value={email} onChange={e => setEmail(e.target.value)} />
                </div>
                <div className="field">
                  <label>Function de poste :</label>
                  <input type="text" value={functionPoste} onChange={e => setFunctionPoste(e.target.value)}/> 
                </div>
              </div>

              <div className="field-row">
                <div className="field">
                  <label>Mod de passe :</label>
                  <input type="password" 
                   value={password} onChange={e => setPassword(e.target.value)} />
                </div>
                <div className="field">
                  <label>Lieu de travail</label>
                  <input type="text"  value={lieuTravail} onChange={e => setlieuTravail(e.target.value)} />
                </div>
              </div>

              <div className="field-row">
                <div className="field full">
                  <label>Expériences et compétences :</label>
                  <input type="text"  value={expirience} onChange={e => setExpirience(e.target.value)} />
                </div>
              </div>

              <div className="field-row">
                <div className="field full">
                  <label>Formation et certifications </label>
                  <input type="text"  value={certificate} onChange={e => setCertificate(e.target.value)} />
                </div>
              </div>
            </div>

            <div className="profile-footer">
              <button className="footer-btn main">modification des information </button>
              <button className="footer-btn">Langue </button>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

